from decimal import Decimal, ROUND_HALF_UP


def import_existing_attempts(apps, schema_editor):
    Attempt = apps.get_model('pedagogie', 'TentativeExercice')
    Participation = apps.get_model('pedagogie', 'ParticipationExercice')
    counts = {}
    for attempt in Attempt.objects.using(schema_editor.connection.alias).order_by('date_creation', 'pk').iterator():
        key = (attempt.eleve_id, attempt.exercice_id)
        counts[key] = counts.get(key, 0) + 1
        attempt.numero = counts[key]
        # Historical booleans already contain the grading result, independently
        # of later edits to questions. Open answers remain pending teacher review.
        if attempt.resultats and all(isinstance(value, bool) for value in attempt.resultats):
            attempt.points_obtenus = sum(attempt.resultats)
            attempt.points_possibles = len(attempt.resultats)
            attempt.note = (Decimal(attempt.points_obtenus) * 20 / attempt.points_possibles).quantize(Decimal('.01'), rounding=ROUND_HALF_UP)
            attempt.date_validation = attempt.date_creation
        attempt.save(using=schema_editor.connection.alias)
    for (student, exercise), used in counts.items():
        Participation.objects.using(schema_editor.connection.alias).create(eleve_id=student, exercice_id=exercise,
            tentatives_autorisees=used, tentatives_utilisees=used)


